def _warn_once(self, kind: str, ref: str) -> None:
        key = (kind, ref)
        if key in self._warned:
            return
        self._warned.add(key)
        _log.warning(
            "StaticModelGateway ignoring requested model %r for kind %r — a "
            "statically-injected client is in use (FR-4 test sugar); wire a real "
            "ModelGateway for per-call resolution", ref, kind,
        )

def run(self, arguments: dict[str, Any], *, ctx: CallContext,
            run: dict[str, Any]) -> str:
        row = self._services.lookup_product(ctx, name=arguments.get("name", ""))
        if row is None:
            return json.dumps({
                "found": False, "hint": LOOKUP_MISS_HINT,
                "catalog": self._services.catalog_index(ctx),
            })
        return json.dumps({"found": True, **row})

def _gate_open(
    keep_going: Callable[[], bool] | None, label: str, kind: object, status: object
) -> bool:
    """One read of the liveness gate. A gate that raises is treated as open (logged):
    a flaky gate read must not turn a recoverable provider hiccup into a failure."""
    if keep_going is None:
        return True
    try:
        open_ = keep_going()
    except Exception:
        _log.exception("%s: liveness gate read failed; continuing to retry", label)
        return True
    if not open_:
        _log.info(
            "%s: owning document no longer processing; abandoning retry "
            "(kind=%s, status=%s)",
            label, kind, status,
        )
    return bool(open_)

def test_create_workspace_is_idempotent(throwaway_ws, tmp_path):
    env = {
        **os.environ,
        **_model_config_env(tmp_path, default_embedding=_DEFAULT_EMBEDDING_REF),
    }

    for _ in range(2):
        result = subprocess.run(
            ["bash", str(_CREATE_WORKSPACE), throwaway_ws],
            env=env,
            capture_output=True,
            text=True,
            timeout=60,
        )
        assert result.returncode == 0, (
            f"create_workspace.sh failed:\nSTDOUT:\n{result.stdout}\nSTDERR:\n{result.stderr}"
        )

    repo = Repository(db.connect())
    overrides = repo.read_model_overrides(throwaway_ws)
    assert overrides["embeddingModel"] == _DEFAULT_EMBEDDING_REF

def _order_cas(self, order_id, expected, new_status, now):
        self.calls.append(("order_cas", order_id, expected, new_status, now))
        order = self.orders.get(order_id)
        if order is None or order["status"] != expected:
            return None
        order["status"] = new_status
        order["updatedAt"] = now
        return {"orderId": order_id, "status": new_status}

