def order_belongs_to_customer(self, ws, *, customer_id, order_id):
        self.calls.append(("order_belongs_to_customer", customer_id, order_id))
        order = self.orders.get(order_id)
        if order is None or order["customerId"] != customer_id:
            return {"owned": False, "status": None}
        return {"owned": True, "status": order["status"]}

def test_shipped_log_config_routes_each_logger_level_to_exactly_one_handler_or_none(tmp_path):
    reach, stdout, stderr = _run_child(tmp_path)

    assert reach == EXPECTED_REACH

    streams = {"stdout": stdout.splitlines(), "stderr": stderr.splitlines()}
    for marker, (stream, text) in PRINTED.items():
        other = "stdout" if stream == "stderr" else "stderr"
        hits = [ln for ln in streams[stream] if marker in ln]
        assert len(hits) == 1, f"{marker}: {len(hits)} lines on {stream}: {hits}"
        assert not [ln for ln in streams[other] if marker in ln], f"{marker} leaked to {other}"
        assert _TS.match(hits[0]), f"{marker}: no ISO 8601 + offset timestamp: {hits[0]!r}"
        assert hits[0][_TS.match(hits[0]).end():].startswith(text), hits[0]
    for marker in DROPPED:
        assert marker not in stdout + stderr, f"{marker} should be dropped"

def _load_method(name: str) -> ast.FunctionDef:
    tree = ast.parse(_REPOSITORY_PATH.read_text(encoding="utf-8"), filename=str(_REPOSITORY_PATH))
    for node in ast.walk(tree):
        if isinstance(node, ast.FunctionDef) and node.name == name:
            return node
    raise AssertionError(f"{name!r} not found in repository.py")

def is_transient(exc: BaseException, *, retry_timeouts: bool = False) -> bool:
    """True when `exc` is a provider failure worth retrying in place (plan §3.1)."""
    if not isinstance(exc, ProviderCallError):
        return False
    if exc.kind == "fallback_exhausted":
        return bool(exc.causes) and all(
            is_transient(cause, retry_timeouts=retry_timeouts) for cause in exc.causes
        )
    if exc.kind in _CONNECTION_KINDS:
        return True
    if exc.kind == "timeout":
        return retry_timeouts
    if exc.kind == "http":
        return (
            exc.status in TRANSIENT_HTTP_STATUSES
            or (exc.status is not None and 500 <= exc.status <= 599)
            or _has_marker(exc.detail)
        )
    if exc.kind == "body_error":
        return _has_marker(exc.detail)
    # "malformed_request", "invalid_json", "body_shape", "response_shape", None
    return False

