def _parse_native_tool_calls(raw: Any) -> list[ToolCall]:
    """Parse the structured OpenAI `message.tool_calls` list into `ToolCall`s.

    Each entry nests the call under `function` with `arguments` as a JSON *string*
    (OpenAI shape); we decode it. LM Studio occasionally hands back an already-parsed
    dict — tolerated. Unparseable/nameless entries are skipped rather than raised.
    """
    if not isinstance(raw, list):
        return []
    calls: list[ToolCall] = []
    for i, entry in enumerate(raw):
        if not isinstance(entry, dict):
            continue
        fn = entry.get("function", entry)
        name = fn.get("name") if isinstance(fn, dict) else None
        if not name:
            continue
        args = _coerce_arguments(fn.get("arguments") if isinstance(fn, dict) else None)
        call_id = entry.get("id") or f"call_{i}"
        calls.append(ToolCall(id=str(call_id), name=str(name), arguments=args))
    return calls

def _validate_path(path: Any) -> None:
    if not isinstance(path, str) or not path:
        raise WorkflowConfigError(
            f"guard `path` must be a non-empty string, got {path!r}"
        )
    head, _, rest = path.partition(".")
    if head not in PATH_ROOTS:
        raise WorkflowConfigError(
            f"guard path root {head!r} is not whitelisted "
            f"(allowed: {', '.join(sorted(PATH_ROOTS))})"
        )
    if head == "ctx" and not rest:
        raise WorkflowConfigError("guard path 'ctx' must name a key, e.g. 'ctx.decision'")
    if rest and any(not segment for segment in rest.split(".")):
        raise WorkflowConfigError(f"guard path {path!r} has an empty segment")

def _serialize_opaque(value: Any) -> str:
    """Serialize a `config`/`guard` value to the opaque string stored in-graph.

    §11 rule 8: `Step.config` and `TRANSITION.guard` are flat serialized strings
    stored verbatim and never queried inside. `None`/missing → `""`; an existing
    string passes through unchanged (already-serialized); anything else is
    compact JSON (stable key order) so re-publishing the same spec is a no-op.
    """
    if value is None:
        return ""
    if isinstance(value, str):
        return value
    return json.dumps(value, separators=(",", ":"), sort_keys=True)

async def _handle_service_error(request, exc):  # noqa: ANN001
        if request.url.path.startswith(API_PREFIX):
            answer = service_error_response(exc)
            if answer is not None:
                status, token = answer
                return JSONResponse(
                    status_code=status,
                    content={"error": token, "detail": str(exc)},
                )
            _log.error(
                "%s reached %s %s with no storefront mapping — the response "
                "carries a Python class name where §5.3 expects a plan token",
                type(exc).__name__, request.method, request.url.path,
            )
        result = inherited(request, exc)
        if inspect.isawaitable(result):
            result = await result
        return result

def __getattr__(self, name):
        if name == self._method:
            def call(*_args, **_kwargs):
                self.calls += 1
                raise self._exc

            return call
        return getattr(self._inner, name)

def _build_query_request_system_prompt(
    schema: querygen.DatasetSchema, *, categories: list[str] | None = None,
) -> str:
    """The internal querygen call's system prompt. With `categories=None` it is
    byte-identical to the pre-K-086 prompt (the `knowledge_base` path)."""
    prompt = _QUERY_REQUEST_INSTRUCTIONS.format(dataset_schema=_describe_dataset_schema(schema))
    if categories:
        prompt += "\n\n" + _CATALOG_CATEGORIES_INSTRUCTION.format(
            categories=", ".join(categories)
        )
    return prompt
